"""Publish a validated batch of generated files together across competing writers."""

import os
from collections.abc import Generator
from contextlib import contextmanager
from pathlib import Path

HEADER = b"# Generated by graphql-typed.\n"


@contextmanager
def _output_lock(output: Path) -> Generator[None, None, None]:
    # OS locks are released if a generator process exits unexpectedly.
    if os.name == "nt":
        import msvcrt

        cache = output / "__pycache__"
        cache.mkdir(exist_ok=True)
        with (cache / "graphql-typed.lock").open("a+b") as lock:
            msvcrt.locking(lock.fileno(), msvcrt.LK_LOCK, 1)
            yield
    else:
        import fcntl

        fd = os.open(output, os.O_RDONLY)
        try:
            fcntl.flock(fd, fcntl.LOCK_EX)
            yield
        finally:
            os.close(fd)


def publish(stage: Path, output: Path) -> None:
    output.mkdir(exist_ok=True)
    with _output_lock(output):
        changed: dict[Path, bytes | None] = {}
        for file in sorted(stage.iterdir()):
            if not file.is_file():
                continue
            dest = output / file.name
            previous = dest.read_bytes() if dest.exists() else None
            if previous and not previous.startswith(HEADER):
                raise ValueError(f"Refusing to replace user file {dest}")
            if file.suffix == ".py":
                file.write_bytes(HEADER + file.read_bytes())
            if previous != file.read_bytes():
                changed[file] = previous

        written = []
        try:
            for file in changed:
                file.replace(output / file.name)
                written.append(file)
                for cache in (output / "__pycache__").glob(f"{file.stem}.*.pyc"):
                    cache.unlink(missing_ok=True)
        except BaseException:
            for file in reversed(written):
                dest = output / file.name
                original = changed[file]
                if original is None:
                    dest.unlink()
                else:
                    file.write_bytes(original)
                    file.replace(dest)
            raise
